def merge(intervals):
    """Return merged disjoint intervals sorted by start.

    Intervals that overlap or touch are combined. The input is not changed.
    """
    if not intervals:
        return []

    ordered = sorted((list(interval) for interval in intervals), key=lambda pair: (pair[0], pair[1]))
    merged = [ordered[0][:]]

    for start, end in ordered[1:]:
        last_start, last_end = merged[-1]
        if start <= last_end:
            if end > last_end:
                merged[-1][1] = end
        else:
            merged.append([start, end])

    return merged
